package com.autohost.api.web;
import com.autohost.api.config.AppProperties;
import jakarta.persistence.*;
import org.springframework.core.io.*;
import org.springframework.http.*;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import java.nio.file.*;
import java.util.*;
@RestController @RequestMapping("/api/workshops")
public class WorkshopController {
 @PersistenceContext EntityManager em; private final AppProperties props;
 private static final String[] F={"nombre","rfc","email","calle","numero","colonia","codigo_postal","estado","municipio"};
 private static final String RFC="(?i)(?:[A-ZÑ&]{3,4})[0-9]{2}(?:0[1-9]|1[0-2])(?:0[1-9]|[12][0-9]|3[01])[A-Z0-9]{3}";
 public WorkshopController(AppProperties props){this.props=props;}
 @PostMapping(consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @Transactional public ResponseEntity<?>create(@RequestParam Map<String,String>b,@RequestPart(value="fotografia",required=false)MultipartFile file){Map<String,String>v=normalize(b);validate(v);if(file==null||file.isEmpty())throw new ApiException(HttpStatus.BAD_REQUEST,"La fotografía del taller es obligatoria.");String route=save(file);String id=UUID.randomUUID().toString();String status="680f54c5-1576-4f1b-98b7-63d4b6a40401";em.createNativeQuery("INSERT INTO Talleres(id,nombre,rfc,email,calle,numero,colonia,codigo_postal,estado,municipio,ruta_fotografia,fk_estatus) VALUES(:id,:nombre,:rfc,:email,:calle,:numero,:colonia,:cp,:estado,:municipio,:photo,:status)").setParameter("id",id).setParameter("nombre",v.get("nombre")).setParameter("rfc",v.get("rfc")).setParameter("email",v.get("email")).setParameter("calle",v.get("calle")).setParameter("numero",v.get("numero")).setParameter("colonia",v.get("colonia")).setParameter("cp",v.get("codigo_postal")).setParameter("estado",v.get("estado")).setParameter("municipio",v.get("municipio")).setParameter("photo",route).setParameter("status",status).executeUpdate();return ResponseEntity.status(201).body(Map.of("message","Taller registrado correctamente.","taller",Map.of("id",id,"nombre",v.get("nombre"),"rfc",v.get("rfc"),"email",v.get("email"),"fk_estatus",status,"ruta_fotografia",route)));}
 @GetMapping @Transactional(readOnly=true) public Map<String,Object>list(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="10")int pageSize){int size=Math.min(50,Math.max(1,pageSize)),p=Math.max(1,page),offset=(p-1)*size;Number total=(Number)em.createNativeQuery("SELECT COUNT(*) FROM Talleres").getSingleResult();List<?>rows=em.createNativeQuery("SELECT t.id,t.nombre,t.rfc,t.email,t.calle,t.numero,t.colonia,t.codigo_postal,t.estado,t.municipio,t.ruta_fotografia,t.fk_estatus,t.IsActive,t.creado_en,e.nombre_estatus FROM Talleres t LEFT JOIN Estatus e ON e.id=t.fk_estatus ORDER BY t.creado_en DESC,t.nombre LIMIT :size OFFSET :offset").setParameter("size",size).setParameter("offset",offset).getResultList();String[]keys={"id","nombre","rfc","email","calle","numero","colonia","codigo_postal","estado","municipio","ruta_fotografia","fk_estatus","IsActive","creado_en","estatus"};List<Map<String,Object>>items=rows.stream().map(row->map((Object[])row,keys)).toList();long count=total.longValue();return Map.of("items",items,"total",count,"page",p,"pageSize",size,"totalPages",(count+size-1)/size);}
 @PutMapping(value="/{id}",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @Transactional public Map<String,String>update(@PathVariable String id,@RequestParam Map<String,String>b,@RequestPart(value="fotografia",required=false)MultipartFile file){Map<String,String>v=normalize(b);validate(v);String photo=file!=null&&!file.isEmpty()?save(file):null;String sql="UPDATE Talleres SET nombre=:nombre,rfc=:rfc,email=:email,calle=:calle,numero=:numero,colonia=:colonia,codigo_postal=:cp,estado=:estado,municipio=:municipio"+(photo==null?"":",ruta_fotografia=:photo")+" WHERE id=:id AND IsActive=1";var q=em.createNativeQuery(sql).setParameter("nombre",v.get("nombre")).setParameter("rfc",v.get("rfc")).setParameter("email",v.get("email")).setParameter("calle",v.get("calle")).setParameter("numero",v.get("numero")).setParameter("colonia",v.get("colonia")).setParameter("cp",v.get("codigo_postal")).setParameter("estado",v.get("estado")).setParameter("municipio",v.get("municipio")).setParameter("id",id);if(photo!=null)q.setParameter("photo",photo);if(q.executeUpdate()==0)throw new ApiException(HttpStatus.NOT_FOUND,"No se encontró el taller activo.");return Map.of("message","Taller actualizado correctamente.");}
 @DeleteMapping("/{id}") @Transactional public Map<String,String>remove(@PathVariable String id){if(em.createNativeQuery("UPDATE Talleres SET IsActive=0 WHERE id=:id AND IsActive=1").setParameter("id",id).executeUpdate()==0)throw new ApiException(HttpStatus.NOT_FOUND,"No se encontró el taller activo.");return Map.of("message","Taller desactivado correctamente.");}
 @GetMapping("/photos/{filename}") public ResponseEntity<Resource>photo(@PathVariable String filename){if(!filename.matches("(?i)[0-9a-f-]{36}\\.(jpg|png|webp)"))throw new ApiException(HttpStatus.NOT_FOUND,"No se encontró la fotografía.");Path path=Paths.get(props.uploadRoot(),"workshops",filename).normalize();if(!Files.isRegularFile(path))throw new ApiException(HttpStatus.NOT_FOUND,"No se encontró la fotografía.");String type=filename.endsWith(".png")?"image/png":filename.endsWith(".webp")?"image/webp":"image/jpeg";return ResponseEntity.ok().contentType(MediaType.parseMediaType(type)).body(new FileSystemResource(path));}
 private Map<String,String>normalize(Map<String,String>b){Map<String,String>m=new HashMap<>();for(String f:F)m.put(f,Objects.toString(b.get(f),"").trim().toLowerCase(Locale.ROOT));return m;}
 private void validate(Map<String,String>v){for(String f:F)if(v.get(f).isBlank())throw new ApiException(HttpStatus.BAD_REQUEST,"El campo "+f.replace('_',' ')+" es obligatorio.");if(!v.get("rfc").matches(RFC))throw new ApiException(HttpStatus.BAD_REQUEST,"El RFC no tiene un formato mexicano válido.");if(!v.get("email").matches("(?i)^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$"))throw new ApiException(HttpStatus.BAD_REQUEST,"El correo electrónico no tiene un formato válido.");if(!v.get("codigo_postal").matches("\\d{5}"))throw new ApiException(HttpStatus.BAD_REQUEST,"El código postal debe contener cinco dígitos.");}
 private String save(MultipartFile f){if(f.getSize()>15L*1024*1024||!Set.of("image/jpeg","image/png","image/webp").contains(f.getContentType()))throw new ApiException(HttpStatus.BAD_REQUEST,"La fotografía debe ser JPG, PNG o WEBP y pesar como máximo 15 MB.");try{String ext=switch(f.getContentType()){case "image/png"->".png";case "image/webp"->".webp";default->".jpg";};String name=UUID.randomUUID()+ext;Path dir=Paths.get(props.uploadRoot(),"workshops");Files.createDirectories(dir);f.transferTo(dir.resolve(name));return "/api/workshops/photos/"+name;}catch(Exception e){throw new ApiException(HttpStatus.INTERNAL_SERVER_ERROR,"No se pudo guardar la fotografía.");}}
 private static Map<String,Object>map(Object[]r,String[]k){Map<String,Object>m=new LinkedHashMap<>();for(int i=0;i<k.length;i++)m.put(k[i],r[i]);return m;}
}
